/**
 * Minimal, dependency-free replacement for the `debug` package.
 *
 * Implements only the subset of the `debug` API that xssec relies on:
 *   const log = debug("xssec");
 *   log.enabled;        // whether the namespace is enabled via the DEBUG env var
 *   log.log = fn;       // override the output sink (defaults to console.error, like debug)
 *   log("message", a);  // logs "<namespace> message" + args when enabled
 *
 * Namespace matching mirrors `debug`: the DEBUG env var is a comma/whitespace
 * separated list of namespaces to enable, where "*" is a wildcard and a leading
 * "-" disables a namespace. Enabled state is resolved once at module load, which
 * matches how xssec is used (DEBUG is set before the process starts).
 */

const skips = [];
const names = [];

/**
 * Converts a debug namespace pattern (with "*" wildcards) into a RegExp.
 * @param {string} pattern
 * @returns {RegExp}
 */
function toRegExp(pattern) {
    const escaped = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*?");
    return new RegExp("^" + escaped + "$");
}

// Parse the DEBUG env var once (debug does the same on load).
const env = process.env.DEBUG || "";
for (const part of env.split(/[\s,]+/)) {
    if (!part) {
        continue;
    }
    if (part[0] === "-") {
        skips.push(toRegExp(part.slice(1)));
    } else {
        names.push(toRegExp(part));
    }
}

/**
 * @param {string} namespace
 * @returns {boolean} whether the given namespace is enabled via DEBUG
 */
function enabled(namespace) {
    if (skips.some((re) => re.test(namespace))) {
        return false;
    }
    return names.some((re) => re.test(namespace));
}

/**
 * Creates a debug logger function for the given namespace.
 * @param {string} namespace
 * @returns {((message?: any, ...args: any[]) => void) & { enabled: boolean, log: Function, namespace: string }}
 */
function debug(namespace) {
    function logger(message, ...args) {
        if (!logger.enabled) {
            return;
        }
        logger.log(`${namespace} ${message}`, ...args);
    }

    logger.namespace = namespace;
    logger.enabled = enabled(namespace);
    logger.log = console.error.bind(console); // debug defaults to stderr; callers may override

    return logger;
}

module.exports = debug;
